css:
.charsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2433;
    background: linear-gradient(160deg, #eef1f6 0%, #e4e8f0 100%);
    border-radius: 18px;
}

.charsim-container * {
    box-sizing: border-box;
}

.charsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #161d2e 0%, #243150 55%, #33436d 100%);
    color: #f4f6fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 29, 46, 0.32);
}

.charsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.charsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0c987;
    background: rgba(240, 201, 135, 0.12);
    padding: 5px 14px;
    border-radius: 999px;
}

.charsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d7deec;
}

.charsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2b3756;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.charsim-period-counter #currentDay,
.charsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #161d2e;
}

.charsim-round-name {
    background: #d6deee;
    color: #243150;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.charsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a5a13;
    background: #fbeed8;
    padding: 4px 12px;
    border-radius: 999px;
}

.charsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.charsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9dfeb;
    box-shadow: 0 4px 14px rgba(22, 29, 46, 0.06);
    border-top: 4px solid #33436d;
}

.charsim-card-gap { border-top-color: #2f6f8f; }
.charsim-card-fit { border-top-color: #b8860b; }
.charsim-card-risk { border-top-color: #b0413c; }
.charsim-card-lift { border-top-color: #3f7d5a; }

.charsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a748c;
}

.charsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #161d2e;
}

.charsim-card-gap .charsim-value { color: #2f6f8f; }
.charsim-card-fit .charsim-value { color: #b8860b; }
.charsim-card-risk .charsim-value { color: #b0413c; }
.charsim-card-lift .charsim-value { color: #3f7d5a; }

.charsim-sublabel {
    font-size: 0.76rem;
    color: #7b859b;
    line-height: 1.35;
}

/* Retention risk: green when low (good), red when high (bad). */
.charsim-risk-low .charsim-value { color: #3f7d5a; }
.charsim-risk-high .charsim-value { color: #b0413c; }
.charsim-risk-high { border-top-color: #b0413c; }
.charsim-risk-low { border-top-color: #3f7d5a; }

.charsim-budget-over { border-top-color: #b0413c; }
.charsim-budget-over .charsim-value { color: #b0413c; }

.charsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #161d2e;
    color: #eef1f8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.charsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0c987;
}

.charsim-budget-bar.charsim-budget-blown #budgetDisplay {
    color: #ff9b8f;
}

.charsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b8860b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 29, 46, 0.05);
}

.charsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.charsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #243150;
    margin-bottom: 6px;
}

.charsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #313a52;
}

.charsim-briefing-text strong { color: #3f7d5a; }
.charsim-briefing-text em { color: #9a5a13; font-style: italic; }

.charsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9dfeb;
    box-shadow: 0 4px 14px rgba(22, 29, 46, 0.06);
}

.charsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #243150;
    border-bottom: 2px solid #e6eaf2;
    padding-bottom: 8px;
}

.charsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3756;
    margin: 14px 0 6px;
}

.charsim-container select,
.charsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2cbdd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7f9fc;
    color: #1d2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.charsim-container select:focus,
.charsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b8860b;
    box-shadow: 0 0 0 3px rgba(184, 134, 11, 0.18);
}

.charsim-container select option {
    background-color: #ffffff;
    color: #1d2433;
}

.charsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b8860b;
}

.charsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f6f8f;
    margin-top: 4px;
}

.charsim-range-readout span:last-child {
    color: #9a5a13;
    font-weight: 800;
}

.charsim-hint {
    font-size: 0.8rem;
    color: #7b859b;
    margin-top: 4px;
    line-height: 1.4;
}

.charsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.charsim-container .btn-primary {
    background: linear-gradient(135deg, #243150 0%, #b8860b 130%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(36, 49, 80, 0.28);
}

.charsim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.charsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2cbdd;
    color: #6a748c;
}

.charsim-coach {
    background: #161d2e;
    color: #eef1f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 29, 46, 0.24);
}

.charsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c987;
    margin-bottom: 8px;
}

.charsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.charsim-coach-body strong { color: #ffd98a; }
.charsim-coach-body em { color: #ffb59f; font-style: italic; }

.charsim-history,
.charsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9dfeb;
    box-shadow: 0 4px 14px rgba(22, 29, 46, 0.06);
}

.charsim-history h3,
.charsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #243150;
}

.charsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2b3756;
}

.charsim-container table#usfHistoryTable th {
    background: #eaeef6;
    color: #243150;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4dcec;
}

.charsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f7;
}

.charsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fafd;
}

.charsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .charsim-container {
        padding: 14px;
    }
    .charsim-header h1 {
        font-size: 1.7rem;
    }
    .charsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .charsim-value {
        font-size: 2rem;
    }
    .charsim-clock {
        margin-left: 0;
    }
    .charsim-period-counter {
        font-size: 0.88rem;
    }
    .charsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .charsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light modal, charsim) ---- */
.charsim-completion { padding: 8px 4px 4px; }
.charsim-cm-head { text-align: center; margin-bottom: 16px; }
.charsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f6a; }
.charsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a9b96; }
.charsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #14213d; }
.charsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.charsim-cm-yes { background: rgba(47,111,106,0.14); color: #256b64; border: 1px solid rgba(47,111,106,0.5); }
.charsim-cm-no { background: rgba(199,154,60,0.16); color: #8a6a1f; border: 1px solid rgba(199,154,60,0.5); }
.charsim-cm-fail { background: rgba(192,57,43,0.12); color: #b0392b; border: 1px solid rgba(192,57,43,0.45); }
.charsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.charsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(20,33,61,0.06); border: 1px solid rgba(20,33,61,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.charsim-cm-metric-risk { background: rgba(192,57,43,0.06); border-color: rgba(192,57,43,0.20); }
.charsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #23304f; }
.charsim-cm-metric-risk .charsim-cm-mv { color: #b0392b; }
.charsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.charsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14213d; }
.charsim-cm-insights { margin: 0; padding-left: 20px; }
.charsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

