(function() {
    'use strict';

    class CharacterAuditAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Character Audit`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (CAD).
            this.START_GAP = 12;
            this.START_FIT = 0;
            this.START_RISK = 70;      // high: Vos may walk with 38% of new ARR
            this.START_LIFT = 15;
            this.BUDGET_CAP = 120;     // CA$120k, in thousands
            this.WIN_GAP = 65;         // credible character-gap closure
            this.WIN_RISK = 40;        // retention risk brought under control
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    gap: this.START_GAP,
                    fit: this.START_FIT,
                    risk: this.START_RISK,
                    lift: this.START_LIFT,
                    budgetUsed: 0,
                    budgetBlown: false,
                    vagueVerdict: false,
                    gapHistory: [this.START_GAP],
                    fitHistory: [this.START_FIT],
                    riskHistory: [this.START_RISK],
                    liftHistory: [this.START_LIFT],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            // Seeded default is deliberately a plausible-but-wrong play (NOT the textbook answer):
            // flat-deficit diagnosis, double-down on Drive, intervention sprawl, weak board case.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    nature: `deficit`,
                    overplayed: `none`,
                    deficient: `integrity`,
                    rigor: 55,
                    priority: `drive`,
                    rec: `retain`,
                    arr: 50,
                    intervention: `sprawl`,
                    spend: 70,
                    measure: `metrics`,
                    threat: `capitulate`,
                    case: `numbers`,
                    embed: `watchlist`,
                    defend: `hedge`,
                    conviction: 65
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const nat = document.getElementById(`natureInput`);
                const ovr = document.getElementById(`overplayedInput`);
                const def = document.getElementById(`deficientInput`);
                const rig = document.getElementById(`rigorInput`);
                if (nat) decisions.nature = nat.value;
                if (ovr) decisions.overplayed = ovr.value;
                if (def) decisions.deficient = def.value;
                if (rig) decisions.rigor = parseInt(rig.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const pri = document.getElementById(`priorityInput`);
                const rec = document.getElementById(`recInput`);
                const arr = document.getElementById(`arrInput`);
                if (pri) decisions.priority = pri.value;
                if (rec) decisions.rec = rec.value;
                if (arr) decisions.arr = parseInt(arr.value, 10);
                if (!Number.isFinite(decisions.arr) || decisions.arr < 0 || decisions.arr > 100) {
                    warn(`warn_arr_range`); return false;
                }
            } else if (round === 3) {
                const intv = document.getElementById(`interventionInput`);
                const sp = document.getElementById(`spendInput`);
                const me = document.getElementById(`measureInput`);
                const th = document.getElementById(`threatInput`);
                if (intv) decisions.intervention = intv.value;
                if (sp) decisions.spend = parseFloat(sp.value);
                if (me) decisions.measure = me.value;
                if (th) decisions.threat = th.value;
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0) {
                    warn(`warn_spend_negative`); return false;
                }
            } else if (round === 4) {
                const ca = document.getElementById(`caseInput`);
                const em = document.getElementById(`embedInput`);
                const de = document.getElementById(`defendInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ca) decisions.case = ca.value;
                if (em) decisions.embed = em.value;
                if (de) decisions.defend = de.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas. risk is INVERTED: a positive riskDelta means risk RISES (bad).
            let gapDelta = 0, fitDelta = 0, riskDelta = 0, liftDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the IMBALANCE at the dimension level (Common Errors 2 & 3).
                switch (d.nature) {
                    case `imbalance`: gapDelta += 12; liftDelta += 5; fitDelta += 4; coachKey = `coach_r1_imbalance`; break;
                    case `deficit`: gapDelta += 3; coachKey = `coach_r1_deficit`; break;
                    case `competence`: gapDelta -= 8; liftDelta -= 4; coachKey = `coach_r1_competence`; break;
                    case `motivation`: gapDelta -= 10; liftDelta -= 4; coachKey = `coach_r1_motivation`; break;
                }

                // Over-played strengths: Drive & Courage are the real over-plays.
                if (d.overplayed === `drivecourage`) {
                    gapDelta += 7;
                } else if (d.overplayed === `humilityjustice`) {
                    gapDelta -= 8; coachKey = `coach_r1_wrongoverplay`;
                } else {
                    gapDelta -= 6; coachKey = `coach_r1_nooverplay`;
                }

                // Deficient dimensions: Temperance/Humility/Collaboration/Justice is the evidenced set.
                if (d.deficient === `temphumcoljus`) {
                    gapDelta += 8; liftDelta += 3; fitDelta += 4;
                    if (d.nature === `imbalance` && d.overplayed === `drivecourage`) coachKey = `coach_r1_sharp`;
                } else if (d.deficient === `integrity`) {
                    gapDelta -= 4; coachKey = `coach_r1_integrity`;
                } else {
                    gapDelta -= 6; coachKey = `coach_r1_wrongdef`;
                }

                // Rigor: dimension-and-behaviour evidence vs a vague verdict (Common Error 3).
                if (d.rigor >= 60) { gapDelta += 6; fitDelta += 6; }
                else if (d.rigor <= 25) { gapDelta -= 8; fitDelta -= 8; ds.vagueVerdict = true; coachKey = `coach_r1_vague`; }

                summaryKey = (d.nature === `imbalance` && d.overplayed === `drivecourage` && d.deficient === `temphumcoljus`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Prioritise the few high-leverage dimensions (KEY CONCEPT: targeted development).
                switch (d.priority) {
                    case `temphum`: gapDelta += 10; liftDelta += 6; fitDelta += 4; coachKey = `coach_r2_temphum`; break;
                    case `temphumcol`: gapDelta += 12; liftDelta += 7; fitDelta += 5; coachKey = `coach_r2_temphumcol`; break;
                    case `allten`: gapDelta -= 6; liftDelta -= 2; fitDelta -= 4; coachKey = `coach_r2_allten`; break;
                    case `drive`: gapDelta -= 10; liftDelta -= 4; riskDelta -= 2; coachKey = `coach_r2_drive`; break;
                }

                // Board recommendation. Hold-the-promotion is the textbook-best; promote-on-numbers
                // is Common Error 1; manage-out-without-developability is Common Error 2.
                switch (d.rec) {
                    case `hold`: gapDelta += 7; liftDelta += 6; riskDelta -= 8; coachKey = (d.priority === `temphum` || d.priority === `temphumcol`) ? `coach_r2_hold` : coachKey; break;
                    case `retain`: gapDelta += 4; liftDelta += 3; riskDelta -= 4; break;
                    case `manageout`: gapDelta -= 6; liftDelta -= 2; riskDelta += 16; coachKey = `coach_r2_manageout`; break;
                    case `promote`: gapDelta -= 12; liftDelta -= 6; riskDelta += 10; coachKey = `coach_r2_promote`; break;
                }

                // De-risk the 38% ARR concentration (FACILITATOR DECISION TREE — inseparable decision).
                if (d.arr >= 60) { riskDelta -= 18; liftDelta += 3; }
                else if (d.arr >= 35) { riskDelta -= 9; }
                else { riskDelta += 6; coachKey = `coach_r2_noarr`; }

                summaryKey = ((d.priority === `temphum` || d.priority === `temphumcol`) && (d.rec === `hold` || d.rec === `retain`) && d.arr >= 35) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Choose ONE high-leverage intervention; the cap binds (Common Error 4).
                let baseSpend = 0, fitBase = 0;
                switch (d.intervention) {
                    case `coaching`: baseSpend = 70; fitBase = 20; gapDelta += 9; liftDelta += 6; coachKey = `coach_r3_coaching`; break;
                    case `cycle360`: baseSpend = 55; fitBase = 22; gapDelta += 11; liftDelta += 5; coachKey = `coach_r3_cycle360`; break;
                    case `stretch`: baseSpend = 40; fitBase = 15; gapDelta += 7; liftDelta += 7; coachKey = `coach_r3_stretch`; break;
                    case `peershadow`: baseSpend = 30; fitBase = 11; gapDelta += 5; liftDelta += 3; coachKey = `coach_r3_peershadow`; break;
                    case `sprawl`: baseSpend = 210; fitBase = 5; gapDelta += 2; coachKey = `coach_r3_sprawl`; break;
                }
                // Spend: take the larger of the chosen lever's base cost and the entered figure.
                spend = Math.max(baseSpend, Number.isFinite(d.spend) ? d.spend : baseSpend);
                fitDelta += fitBase;

                // The CA$120k cap binds: overshooting it costs fit, gap and lift — the board pulls it.
                if (spend > this.BUDGET_CAP) {
                    ds.budgetBlown = true;
                    fitDelta -= 20; gapDelta -= 8; liftDelta -= 4;
                    coachKey = `coach_r3_overbudget`;
                } else if (spend <= this.BUDGET_CAP && d.intervention !== `sprawl`) {
                    fitDelta += 6; // well-scoped within budget
                }

                // Measurement & consequence (Common Error 5).
                switch (d.measure) {
                    case `full`: fitDelta += 16; gapDelta += 7; coachKey = (spend <= this.BUDGET_CAP && d.intervention !== `sprawl`) ? `coach_r3_fullmeasure` : coachKey; break;
                    case `metrics`: fitDelta += 5; gapDelta += 2; break;
                    case `none`: fitDelta -= 14; gapDelta -= 6; coachKey = `coach_r3_nomeasure`; break;
                }

                // Vos's defensiveness + competitor approach.
                switch (d.threat) {
                    case `firmsupport`: gapDelta += 4; riskDelta -= 10; liftDelta += 2; break;
                    case `capitulate`: gapDelta -= 8; riskDelta -= 4; liftDelta -= 4; fitDelta -= 4; coachKey = `coach_r3_capitulate`; break;
                    case `ultimatum`: gapDelta -= 4; riskDelta += 16; coachKey = `coach_r3_ultimatum`; break;
                }

                summaryKey = (d.intervention !== `sprawl` && spend <= this.BUDGET_CAP && d.measure === `full`) ? `sum_r3_good` : (ds.budgetBlown ? `sum_r3_blown` : `sum_r3_weak`);
            } else if (round === 4) {
                // Make the business case: character as performance & governance data (Common Error 1).
                switch (d.case) {
                    case `performancedata`: gapDelta += 6; liftDelta += 10; fitDelta += 4; coachKey = `coach_r4_perfdata`; break;
                    case `softskill`: liftDelta += 3; coachKey = `coach_r4_softskill`; break;
                    case `numbers`: gapDelta -= 6; liftDelta -= 6; riskDelta += 4; coachKey = `coach_r4_numbers`; break;
                }

                // Institutionalise character in the talent / promotion process.
                switch (d.embed) {
                    case `promotion`: gapDelta += 8; liftDelta += 8; riskDelta -= 6; break;
                    case `watchlist`: liftDelta += 2; coachKey = `coach_r4_watchlist`; break;
                    case `oneoff`: gapDelta -= 4; liftDelta -= 4; coachKey = `coach_r4_oneoff`; break;
                }

                // Defend it as measurable / developable / defensible.
                switch (d.defend) {
                    case `measurable`: gapDelta += 8; liftDelta += 6; fitDelta += 4; coachKey = (d.case === `performancedata` && d.embed === `promotion`) ? `coach_r4_measurable` : coachKey; break;
                    case `hedge`: gapDelta -= 4; liftDelta -= 2; coachKey = `coach_r4_hedge`; break;
                    case `retreat`: gapDelta -= 10; liftDelta -= 8; riskDelta += 8; coachKey = `coach_r4_retreat`; break;
                }

                // Conviction nudges effectiveness lift.
                liftDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = (d.case === `performancedata` && d.embed === `promotion` && d.defend === `measurable`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (budget only spent in round 3).
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round(ds.budgetUsed + spend));

            // Apply deltas with 0–100 clamps. risk rises with positive riskDelta.
            ds.gap = Math.max(0, Math.min(100, ds.gap + gapDelta));
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.risk = Math.max(0, Math.min(100, ds.risk + riskDelta));
            ds.lift = Math.max(0, Math.min(100, ds.lift + liftDelta));

            ds.gapHistory.push(Math.round(ds.gap));
            ds.fitHistory.push(Math.round(ds.fit));
            ds.riskHistory.push(Math.round(ds.risk));
            ds.liftHistory.push(Math.round(ds.lift));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                gap: Math.round(ds.gap),
                gapDelta: Math.round(gapDelta),
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                risk: Math.round(ds.risk),
                riskDelta: Math.round(riskDelta),
                lift: Math.round(ds.lift),
                liftDelta: Math.round(liftDelta),
                budgetUsed: ds.budgetUsed,
                budgetBlown: ds.budgetBlown,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

