        _composite(ds) {
            const gap = Math.round(ds.gap);
            const fit = Math.round(ds.fit);
            const risk = Math.round(ds.risk);
            const lift = Math.round(ds.lift);
            const composite = Math.round(gap * 0.30 + fit * 0.25 + (100 - risk) * 0.25 + lift * 0.20);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="charsim-cm-badge charsim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="charsim-cm-badge charsim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.vagueVerdict) failBadges += ` <span class="charsim-cm-badge charsim-cm-fail">` + T(`cm_vague`) + `</span>`;
            if (s.budgetBlown) failBadges += ` <span class="charsim-cm-badge charsim-cm-fail">` + T(`cm_blown`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="charsim-cm-metric"><span class="charsim-cm-mv">` + Math.round(s.gap || 0) + `</span><span class="charsim-cm-ml">` + T(`cm_m_gap`) + `</span></div>`
                + `<div class="charsim-cm-metric"><span class="charsim-cm-mv">` + Math.round(s.fit || 0) + `</span><span class="charsim-cm-ml">` + T(`cm_m_fit`) + `</span></div>`
                + `<div class="charsim-cm-metric charsim-cm-metric-risk"><span class="charsim-cm-mv">` + Math.round(s.risk || 0) + `</span><span class="charsim-cm-ml">` + T(`cm_m_risk`) + `</span></div>`
                + `<div class="charsim-cm-metric"><span class="charsim-cm-mv">` + Math.round(s.lift || 0) + `</span><span class="charsim-cm-ml">` + T(`cm_m_lift`) + `</span></div>`;
            return ``
                + `<div class="charsim-completion">`
                +   `<div class="charsim-cm-head">`
                +     `<div class="charsim-cm-score">` + score + `<span class="charsim-cm-score-max">/100</span></div>`
                +     `<div class="charsim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="charsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="charsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="charsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const gap = Math.round(ds.gap);
            const fit = Math.round(ds.fit);
            const risk = Math.round(ds.risk);
            const lift = Math.round(ds.lift);

            const closedGap = gap >= this.WIN_GAP;
            const riskControlled = risk <= this.WIN_RISK;
            const goodFit = fit >= 55;
            // Composite: gap + fit + lift reward closure; risk inverted. Single source of truth: _composite(ds).
            const composite = this._composite(ds);

            let performanceKey = `grade_verdict`;
            if (closedGap && riskControlled && goodFit && composite >= 70) performanceKey = `grade_measured`;
            else if (closedGap && riskControlled && goodFit) performanceKey = `grade_defensible`;
            else if (closedGap && !riskControlled) performanceKey = `grade_cliff`;
            else if (!closedGap && composite >= 50) performanceKey = `grade_partial`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (closedGap && riskControlled && goodFit) insights.push(window.mySimulation.t(`insight_measured`));
            else if (closedGap && !riskControlled) insights.push(window.mySimulation.t(`insight_cliff`));
            else if (!closedGap && composite >= 50) insights.push(window.mySimulation.t(`insight_partial`));
            else insights.push(window.mySimulation.t(`insight_verdict`));

            if (ds.vagueVerdict) insights.push(window.mySimulation.t(`insight_vague`));
            if (ds.budgetBlown) insights.push(window.mySimulation.t(`insight_blown`));
            if (fit < 45) insights.push(window.mySimulation.t(`insight_lowfit`));
            if (risk > 60) insights.push(window.mySimulation.t(`insight_highrisk`));
            if (closedGap && riskControlled && goodFit && lift >= 55) insights.push(window.mySimulation.t(`insight_governance`));

            return {
                gap: gap,
                fit: fit,
                risk: risk,
                lift: lift,
                closedGap: closedGap,
                riskControlled: riskControlled,
                sound: closedGap && riskControlled && goodFit,
                vagueVerdict: ds.vagueVerdict,
                budgetBlown: ds.budgetBlown,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.budgetBlown) return window.mySimulation.t(`hint_blown`);
            if (ds.vagueVerdict) return window.mySimulation.t(`hint_vague`);
            if (ds.risk > 60 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_risk`);
            if (ds.fit < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_fit`);
            if (ds.gap >= this.WIN_GAP && ds.risk <= this.WIN_RISK && ds.fit >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

